<body>
<div class="wrap">
  <header>
    <div>
      <h1>Memory Match</h1>
      <p class="hint">Flip two cards to find a pair. Clear all 8 pairs to win.</p>
    </div>
    <div class="stats">
      <div class="stat"><div class="v" id="moves">0</div><div class="l">Moves</div></div>
      <div class="stat"><div class="v" id="found">0/8</div><div class="l">Found</div></div>
      <div class="stat"><div class="v" id="best">—</div><div class="l">Best</div></div>
    </div>
  </header>

  <div class="board" id="board" role="group" aria-label="Memory card board"></div>

  <div class="controls">
    <button class="btn" id="newGame">New game</button>
  </div>

  <div class="win" id="win" hidden>
    <h2>You won!</h2>
    <p id="winText"></p>
    <button class="btn secondary" id="playAgain">Play again</button>
  </div>

  <p class="sr" id="live" role="status" aria-live="polite"></p>
</div>

<script>
const KEY = 'memory-match-v1';
const SYMBOLS = ['🌙','🍁','🌊','🔥','⭐','🌸','🍄','⚡'];
const board = document.getElementById('board');
const movesEl = document.getElementById('moves');
const foundEl = document.getElementById('found');
const bestEl = document.getElementById('best');
const winBox = document.getElementById('win');
const winText = document.getElementById('winText');
const live = document.getElementById('live');

let cards = [];
let first = null, second = null;
let lock = false;
let moves = 0, matched = 0;
let best = null;
let timers = [];

function hasStorage(){ return !!(window.alfy && window.alfy.storage); }

function shuffle(a){
  for(let i=a.length-1;i>0;i--){
    const j = Math.floor(Math.random()*(i+1));
    [a[i],a[j]] = [a[j],a[i]];
  }
  return a;
}

function clearTimers(){ timers.forEach(clearTimeout); timers = []; }

function buildDeck(){
  const deck = shuffle([...SYMBOLS, ...SYMBOLS]);
  return deck.map((sym,i)=>({ id:i, sym, matched:false, flipped:false }));
}

function render(){
  board.innerHTML = '';
  cards.forEach(c=>{
    const btn = document.createElement('button');
    btn.className = 'card';
    btn.dataset.id = c.id;
    btn.setAttribute('aria-pressed','false');
    btn.setAttribute('aria-label','Card ' + (c.id+1) + (c.matched ? ', matched' : ', face down'));
    btn.innerHTML =
      '<span class="card-inner">' +
        '<span class="face back" aria-hidden="true">✦</span>' +
        '<span class="face front" aria-hidden="true">' + c.sym + '</span>' +
      '</span>';
    btn.addEventListener('click', ()=>onFlip(c.id, btn));
    board.appendChild(btn);
  });
}

function cardEl(id){ return board.querySelector('[data-id="'+id+'"]'); }

function onFlip(id, el){
  if(lock) return;
  const c = cards[id];
  if(c.matched || c.flipped) return;
  c.flipped = true;
  el.classList.add('flipped');
  el.setAttribute('aria-pressed','true');
  el.setAttribute('aria-label','Card ' + (id+1) + ', showing ' + c.sym);

  if(first === null){ first = id; return; }
  second = id;
  lock = true;
  moves++;
  movesEl.textContent = moves;

  if(cards[first].sym === cards[second].sym){
    matched++;
    foundEl.textContent = matched + '/8';
    const a = first, b = second;
    const t = setTimeout(()=>{
      cards[a].matched = true; cards[b].matched = true;
      cardEl(a).classList.add('matched'); cardEl(b).classList.add('matched');
      cardEl(a).setAttribute('aria-label','Card '+(a+1)+', matched');
      cardEl(b).setAttribute('aria-label','Card '+(b+1)+', matched');
      first = second = null; lock = false;
      live.textContent = 'Match found. ' + matched + ' of 8 pairs.';
      if(matched === 8) win();
    }, 480);
    timers.push(t);
  } else {
    const a = first, b = second;
    const t = setTimeout(()=>{
      cards[a].flipped = false; cards[b].flipped = false;
      cardEl(a).classList.remove('flipped'); cardEl(b).classList.remove('flipped');
      cardEl(a).setAttribute('aria-pressed','false'); cardEl(b).setAttribute('aria-pressed','false');
      cardEl(a).setAttribute('aria-label','Card '+(a+1)+', face down');
      cardEl(b).setAttribute('aria-label','Card '+(b+1)+', face down');
      first = second = null; lock = false;
      live.textContent = 'No match. ' + moves + ' moves.';
    }, 850);
    timers.push(t);
  }
}

function win(){
  if(best === null || moves < best){ best = moves; save(); }
  bestEl.textContent = best;
  winText.textContent = 'You cleared the board in ' + moves + ' moves.';
  winBox.hidden = false;
  live.textContent = 'You won in ' + moves + ' moves!';
}

function newGame(){
  clearTimers();
  first = second = null; lock = false;
  moves = 0; matched = 0;
  movesEl.textContent = '0';
  foundEl.textContent = '0/8';
  winBox.hidden = true;
  cards = buildDeck();
  render();
  live.textContent = 'New game started. 8 pairs to find.';
  save();
}

function save(){
  if(!hasStorage()) return;
  window.alfy.storage.set(KEY, { cards, moves, matched, best });
}

async function load(){
  if(hasStorage()){
    try{
      const s = await window.alfy.storage.get(KEY);
      if(s && Array.isArray(s.cards) && s.cards.length === 16){
        cards = s.cards; moves = s.moves|0; matched = s.matched|0; best = s.best;
        bestEl.textContent = best === null ? '—' : best;
        render();
        // restore visual state of previously flipped/matched cards
        cards.forEach(c=>{
          const el = cardEl(c.id);
          if(c.matched){ el.classList.add('flipped','matched'); el.setAttribute('aria-label','Card '+(c.id+1)+', matched'); }
          else if(c.flipped){ el.classList.add('flipped'); el.setAttribute('aria-pressed','true'); }
        });
        movesEl.textContent = moves;
        foundEl.textContent = matched + '/8';
        if(matched === 8){ winText.textContent = 'You cleared the board in ' + moves + ' moves.'; winBox.hidden = false; }
        return;
      }
    }catch(e){}
  }
  cards = buildDeck();
  render();
}

document.getElementById('newGame').addEventListener('click', newGame);
document.getElementById('playAgain').addEventListener('click', newGame);

load();
</script>
</body>
</html>
